INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Menaces envers un élu local', 'CGD Bourg-en-Bresse', 'GGD 01', 'Ain', 'Parcieux', 'Un élu local fait état de la réception, à sa permanence et à son domicile, de plusieurs courriers anonymes au ton menaçant sur une période courte. Les écrits, au vocabulaire revendicatif, sont explicitement liés à un projet d''aménagement contesté sur la commune. Aucune menace de passage à l''acte datée n''y figure, mais la répétition et la montée en intensité inquiètent l''intéressé, qui a modifié ses habitudes. Aucun auteur n''est identifié à ce stade ; un rapprochement est à effectuer avec les prises de position publiques récentes sur le dossier. Les originaux ont été conservés. Renseignement à suivre et à recouper avec d''éventuels faits similaires visant d''autres élus du secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'élu', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'menaces', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Propos préoccupants en ligne', 'BR Bourg-en-Bresse', 'GGD 01', 'Ain', 'Pont-d''Ain', 'Signalement émanant d''un proche faisant état d''un changement rapide et marqué de comportement chez un individu : rupture avec l''entourage habituel, adoption d''un discours rigoriste et rejet des institutions sur une période courte. L''intéressé, contrôlé lors d''un déplacement routier, a été identifié : Léa NGUYEN, né(e) le 03/12/1988 ; aucune infraction relevée à cette occasion. Le proche décrit un repli progressif et de nouvelles fréquentations mal identifiées. Aucun élément ne permet à ce stade de caractériser un projet ou une menace. Renseignement à évaluer avec mesure, à recouper avec les autres remontées et à porter, le cas échéant, à la connaissance des services spécialisés.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
