INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'ordre public', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Point de deal présumé', 'COB Évreux', 'GGD 27', 'Eure', 'Berville-sur-Mer', 'Va-et-vient nocturnes réguliers observés autour d''un hall d''immeuble, principalement en fin de soirée et en début de nuit, avec présence de guetteurs postés en entrée de rue et en pied d''immeuble donnant l''alerte à l''approche de tout véhicule. Une berline sombre (immatriculation JL-838-KK) effectue des passages courts et répétés, marquant de brefs arrêts avant de repartir. Les échanges, rapides et discrets, sont cohérents avec une activité de vente au détail. Plusieurs habitants font état d''un climat d''intimidation et évitent désormais les parties communes en soirée. Aucun mis en cause identifié à ce jour ; renseignement à recouper avec les doléances déjà enregistrées sur le secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'stupéfiants', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'deal', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'guet', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Changement de comportement signalé', 'COB Les Andelys', 'GGD 27', 'Eure', 'Broglie', 'Signalement émanant d''un proche faisant état d''un changement rapide et marqué de comportement chez un individu : rupture avec l''entourage habituel, adoption d''un discours rigoriste et rejet des institutions sur une période courte. L''intéressé, contrôlé lors d''un déplacement routier, a été identifié : Sarah MOREAU, né(e) le 15/09/2006 ; aucune infraction relevée à cette occasion. Le proche décrit un repli progressif et de nouvelles fréquentations mal identifiées. Aucun élément ne permet à ce stade de caractériser un projet ou une menace. Renseignement à évaluer avec mesure, à recouper avec les autres remontées et à porter, le cas échéant, à la connaissance des services spécialisés.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
