INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Groupe de supporters à risque', 'COB Brest', 'GGD 29', 'Finistère', 'Saint-Sauveur', 'Déplacement annoncé d''un groupe de supporters classé à risque à l''occasion d''une rencontre à l''extérieur, avec constitution d''un convoi routier repéré sur l''axe principal (dont un véhicule immatriculé PT-132-EQ). Les échanges en amont, relayés dans des espaces de discussion fermés, laissent entrevoir une volonté de confrontation avec les supporters adverses. Les horaires et points de convergence évoquent un rendez-vous coordonné. Aucun incident constaté au moment de la remontée. Éléments à porter à la connaissance des unités concernées le long de l''itinéraire et à recouper avec les renseignements d''ordre public existants.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'supporters', 0);
