INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Propos préoccupants en ligne', 'BTA Albertville', 'GGD 73', 'Savoie', 'Porte-de-Savoie', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @ombre_noire (instagram.com/libre_2026) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Kevin MARTIN, né(e) le 20/01/1982 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
