INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Groupe de développement personnel signalé', 'BTA Thonon-les-Bains', 'GGD 74', 'Haute-Savoie', 'Ayse', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Mehdi MARTIN, né(e) le 04/01/1987 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Attroupement et jets de projectiles', 'COB Bonneville', 'GGD 74', 'Haute-Savoie', 'Chaumont', 'Depuis une dizaine de jours, signalements répétés de rodéos motorisés en soirée, principalement entre 21h00 et minuit, sur les axes desservant le quartier et ses abords immédiats. Un deux-roues non homologué (50cc débridé) apparaît impliqué à plusieurs reprises ; immatriculation partielle relevée par un riverain : RA-631-JD. Les individus, décrits comme de jeunes majeurs résidant vraisemblablement sur place, adoptent une conduite dangereuse (roues arrière prolongées, remontées de file, franchissements de feux) et se dispersent à l''approche des patrouilles. Aucun n''a pu être formellement identifié à ce stade. Nuisances sonores nocturnes et sentiment d''insécurité croissants rapportés par plusieurs familles ; phénomène à surveiller et à recouper avec les mains courantes des unités voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'rodéo', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'deux-roues', 1);
