INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Rodéos motorisés récurrents', 'BTA Orange', 'GGD 84', 'Vaucluse', 'Lagnes', 'Depuis une dizaine de jours, signalements répétés de rodéos motorisés en soirée, principalement entre 21h00 et minuit, sur les axes desservant le quartier et ses abords immédiats. Un deux-roues non homologué (50cc débridé) apparaît impliqué à plusieurs reprises ; immatriculation partielle relevée par un riverain : XH-200-QV. Les individus, décrits comme de jeunes majeurs résidant vraisemblablement sur place, adoptent une conduite dangereuse (roues arrière prolongées, remontées de file, franchissements de feux) et se dispersent à l''approche des patrouilles. Aucun n''a pu être formellement identifié à ce stade. Nuisances sonores nocturnes et sentiment d''insécurité croissants rapportés par plusieurs familles ; phénomène à surveiller et à recouper avec les mains courantes des unités voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'rodéo', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'deux-roues', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'nuisances', 2);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Tract appelant au blocage', 'BR Avignon', 'GGD 84', 'Vaucluse', 'Cavaillon', 'Deux personnes ont été observées photographiant et filmant les accès, clôtures et postes de contrôle d''un site industriel classé, avant de se replier à bord d''un véhicule de tourisme (immatriculation SR-433-WL) stationné à l''écart. Leur comportement (repérage méthodique des points d''entrée, attention portée aux caméras et aux horaires de rondes) évoque une phase de préparation. En parallèle, une mobilisation visant ce type d''installations est relayée en ligne sur t.me/faucon_du_nord. Aucune action n''a été engagée sur place à ce jour. Éléments à rapprocher des appels militants en cours et à porter à la connaissance de l''exploitant pour renforcement de la vigilance ; suivi à assurer.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'blocage', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'site', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Groupe de développement personnel signalé', 'BTA Avignon', 'GGD 84', 'Vaucluse', 'Maubec', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Nadia PETIT, né(e) le 25/07/1993 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Dégradation de permanence', 'BTA Orange', 'GGD 84', 'Vaucluse', 'Suzette', 'Un élu local fait état de la réception, à sa permanence et à son domicile, de plusieurs courriers anonymes au ton menaçant sur une période courte. Les écrits, au vocabulaire revendicatif, sont explicitement liés à un projet d''aménagement contesté sur la commune. Aucune menace de passage à l''acte datée n''y figure, mais la répétition et la montée en intensité inquiètent l''intéressé, qui a modifié ses habitudes. Aucun auteur n''est identifié à ce stade ; un rapprochement est à effectuer avec les prises de position publiques récentes sur le dossier. Les originaux ont été conservés. Renseignement à suivre et à recouper avec d''éventuels faits similaires visant d''autres élus du secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'élu', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'menaces', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-17', 'Détention d''arme signalée', 'BTA Carpentras', 'GGD 84', 'Vaucluse', 'Roussillon', 'Signalement faisant état de la détention possible d''une arme de poing par un individu au comportement menaçant, qui l''aurait exhibée ou évoquée à l''occasion d''un différend de voisinage. La source, indirecte, rapporte des propos alarmants tenus par l''intéressé. Un véhicule (immatriculation PM-114-KP) lui est associé. Aucune arme n''a été constatée directement par les enquêteurs à ce stade, et l''origine comme la nature exacte de l''objet restent à établir. La montée de tension locale justifie une évaluation attentive. Renseignement à recouper avec les antécédents éventuels et à sécuriser en vue d''une possible judiciarisation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'arme', 0);
