INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Groupe de développement personnel signalé', 'CGD Guéret', 'GGD 23', 'Creuse', 'Faux-la-Montagne', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Nadia FERHAT, né(e) le 10/03/1972 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Détention d''arme signalée', 'CGD Guéret', 'GGD 23', 'Creuse', 'Reterre', 'Renseignement faisant état d''une transaction d''arme présumée devant intervenir sur un parking isolé, à l''écart des zones fréquentées et sur un créneau discret. Un participant, contrôlé à proximité, a été identifié : Yanis LEROY, né(e) le 27/10/1999. Les modalités décrites (rendez-vous bref, remise d''un objet volumineux dissimulé, méfiance marquée des protagonistes) sont cohérentes avec un échange clandestin, sans que la nature de l''objet soit établie. Aucune saisie n''a été opérée. La fiabilité de la source reste à confirmer. Élément à recouper d''urgence avec les renseignements relatifs au trafic d''armes dans le secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'arme', 0);
