INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Tract appelant au blocage', 'COB Pontarlier', 'GGD 25', 'Doubs', 'Pays-de-Clerval', 'Distribution de tracts sur la voie publique appelant au blocage d''un chantier local présenté comme écologiquement contesté, l''appel étant également relayé par le compte @nuit_du_sud (t.me/libre_2026) annonçant une action à venir. Un participant, contrôlé sur place lors de la distribution, a été identifié : Bilal MASSON, né(e) le 22/11/1999, déjà connu(e) pour sa participation à des actions de blocage. Le discours diffusé prône une mobilisation déterminée mais ne comporte pas d''appel explicite à la violence. La date et le lieu précis de l''action annoncée restent à confirmer. Renseignement à recouper avec les mouvements militants régionaux et à intégrer à l''anticipation des troubles à l''ordre public.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
