INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Changement de comportement signalé', 'BTA Cholet', 'GGD 49', 'Maine-et-Loire', 'Val-du-Layon', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @faucon_du_nord (x.com/oeil_ouvert) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Léa DUBOIS, né(e) le 18/10/1975 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
