INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Groupe de développement personnel signalé', 'BR Vannes', 'GGD 56', 'Morbihan', 'Groix', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Rachid MARTIN, né(e) le 15/11/1970 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
