INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Intrusions sur exploitation', 'COB Chalon-sur-Saône', 'GGD 71', 'Saône-et-Loire', 'Devrouze', 'Série de vols de GPS de guidage, de batteries et d''outillage spécialisé commis sur plusieurs exploitations agricoles isolées d''un même secteur, sur une période resserrée. Les faits, commis de nuit, visent des matériels de valeur revendables et dénotent une bonne connaissance des lieux et des équipements ciblés. Une camionnette (immatriculation WE-902-KN) a été signalée circulant de nuit sur les chemins ruraux desservant les parcelles concernées. Les exploitants déplorent un préjudice cumulé important et un sentiment d''exposition croissant. Aucun auteur interpellé à ce jour. Faits à rapprocher d''une possible équipe itinérante et à recouper avec les vols similaires des départements limitrophes.');
