INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-18', 'Faux agents à domicile', 'BTA Melun', 'GGD 77', 'Seine-et-Marne', 'Boissettes', 'Plusieurs personnes âgées d''un même secteur ont été démarchées à domicile, sur une courte période, par un individu se présentant comme agent d''un service public et exhibant un badge non vérifiable. Sous prétexte d''un contrôle technique ou administratif urgent, l''homme tente d''obtenir l''accès au logement et de détourner l''attention des occupants. Un véhicule utilitaire blanc (immatriculation QX-914-ZX) est associé à ces passages. Aucune remise de fonds n''est confirmée à ce stade, mais le mode opératoire est caractéristique des équipes itinérantes de faux agents. Les victimes, isolées, n''ont pas toutes conservé de description précise. Renseignement à diffuser en prévention et à recouper avec les faits des communes voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
