INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-19', 'Propos préoccupants en ligne', 'PSIG Bourg-en-Bresse', 'GGD 01', 'Ain', 'Évosges', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @colere_rurale (discord.gg/resistance84) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Émilie DA SILVA, né(e) le 19/05/1996 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
