INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-19', 'Dégradation de permanence', 'BTA Saint-Lô', 'GGD 50', 'Manche', 'Saint-Planchers', 'Un élu local fait état de la réception, à sa permanence et à son domicile, de plusieurs courriers anonymes au ton menaçant sur une période courte. Les écrits, au vocabulaire revendicatif, sont explicitement liés à un projet d''aménagement contesté sur la commune. Aucune menace de passage à l''acte datée n''y figure, mais la répétition et la montée en intensité inquiètent l''intéressé, qui a modifié ses habitudes. Aucun auteur n''est identifié à ce stade ; un rapprochement est à effectuer avec les prises de position publiques récentes sur le dossier. Les originaux ont été conservés. Renseignement à suivre et à recouper avec d''éventuels faits similaires visant d''autres élus du secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'élu', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'menaces', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-19', 'Tensions autour d''une rencontre sportive', 'EDSR 50', 'GGD 50', 'Manche', 'Montpinchon', 'En marge d''une rencontre sportive, un groupe de supporters a été signalé pour un comportement agressif aux abords de l''enceinte : usage de fumigènes, provocations et échauffourées évitées de justesse grâce au dispositif en place. Un individu, contrôlé à cette occasion, a été identifié : Lucas MARCHAND, né(e) le 23/08/1976, déjà connu pour des faits similaires. Des tensions préexistantes avec un groupe rival sont rapportées et pourraient ressurgir lors des prochaines échéances. Aucune interpellation pour violences à ce stade. Renseignement à intégrer à la préparation des futurs matchs et à recouper avec les fiches des groupes à risque connus au plan régional.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'supporters', 0);
