INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'exploitation', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-19', 'Emprise sur personne vulnérable', 'COB Sens', 'GGD 89', 'Yonne', 'Égleny', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Bilal ROUSSEAU, né(e) le 13/10/1994 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-19', 'Propos préoccupants en ligne', 'COB Sens', 'GGD 89', 'Yonne', 'Thory', 'Signalement émanant d''un proche faisant état d''un changement rapide et marqué de comportement chez un individu : rupture avec l''entourage habituel, adoption d''un discours rigoriste et rejet des institutions sur une période courte. L''intéressé, contrôlé lors d''un déplacement routier, a été identifié : Léa BENNANI, né(e) le 24/12/1982 ; aucune infraction relevée à cette occasion. Le proche décrit un repli progressif et de nouvelles fréquentations mal identifiées. Aucun élément ne permet à ce stade de caractériser un projet ou une menace. Renseignement à évaluer avec mesure, à recouper avec les autres remontées et à porter, le cas échéant, à la connaissance des services spécialisés.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
