INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Va-et-vient suspects nocturnes', 'BR Privas', 'GGD 07', 'Ardèche', 'Vesseaux', 'Transactions rapides signalées de manière récurrente sur un parking de zone commerciale en périphérie, en journée comme en soirée. Deux individus reviennent régulièrement, dont l''un circulant à scooter (immatriculation XF-283-LK) et l''autre à pied, effectuant des contacts brefs avec des occupants de véhicules qui repartent aussitôt. Le fonctionnement (rendez-vous minutés, points de rencontre changeants) évoque une logistique de livraison. Aucun produit ni somme n''a été constaté directement. Éléments d''ambiance à confirmer par surveillance et à rapprocher des renseignements des unités limitrophes.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'stupéfiants', 0);
