INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Va-et-vient suspects nocturnes', 'COB Aurillac', 'GGD 15', 'Cantal', 'Pleaux', 'Va-et-vient nocturnes réguliers observés autour d''un hall d''immeuble, principalement en fin de soirée et en début de nuit, avec présence de guetteurs postés en entrée de rue et en pied d''immeuble donnant l''alerte à l''approche de tout véhicule. Une berline sombre (immatriculation XT-656-VS) effectue des passages courts et répétés, marquant de brefs arrêts avant de repartir. Les échanges, rapides et discrets, sont cohérents avec une activité de vente au détail. Plusieurs habitants font état d''un climat d''intimidation et évitent désormais les parties communes en soirée. Aucun mis en cause identifié à ce jour ; renseignement à recouper avec les doléances déjà enregistrées sur le secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'stupéfiants', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'deal', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'guet', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Vols de matériel agricole', 'EDSR 15', 'GGD 15', 'Cantal', 'Albepierre-Bredons', 'Série de vols de GPS de guidage, de batteries et d''outillage spécialisé commis sur plusieurs exploitations agricoles isolées d''un même secteur, sur une période resserrée. Les faits, commis de nuit, visent des matériels de valeur revendables et dénotent une bonne connaissance des lieux et des équipements ciblés. Une camionnette (immatriculation ZX-794-ZL) a été signalée circulant de nuit sur les chemins ruraux desservant les parcelles concernées. Les exploitants déplorent un préjudice cumulé important et un sentiment d''exposition croissant. Aucun auteur interpellé à ce jour. Faits à rapprocher d''une possible équipe itinérante et à recouper avec les vols similaires des départements limitrophes.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'agricole', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vol', 1);
