INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Démarchage frauduleux de séniors', 'COB Muret', 'GGD 31', 'Haute-Garonne', 'Saint-Rome', 'Vague d''appels téléphoniques ciblant des séniors isolés, l''interlocuteur usurpant la qualité d''agent administratif ou bancaire pour instaurer un climat d''urgence. Sous couvert d''une prétendue anomalie sur un compte ou d''un remboursement à régulariser, il cherche à obtenir des coordonnées bancaires, des codes ou un rendez-vous à domicile. Plusieurs personnes rapportent des appels répétés depuis des numéros masqués ou usurpés. Le discours, rodé et insistant, vise à contourner la méfiance des victimes. Aucun préjudice financier n''est confirmé pour l''instant. Phénomène à signaler en prévention et à rapprocher des campagnes d''escroquerie recensées au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'personnes âgées', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'démarchage', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Démarchage par faux agent — mode opératoire identique', 'COB Toulouse', 'GGD 31', 'Haute-Garonne', 'Moncaup', 'Personne âgée démarchée à son domicile par un homme se présentant comme agent d''un organisme officiel, muni d''un gilet et d''un badge non vérifiables. Même mode opératoire que d''autres faits récents : prétexte d''un contrôle urgent (compteur, canalisation, mise aux normes), insistance pour entrer, tentative de détourner l''attention pendant qu''un second individu resterait à l''extérieur. Un véhicule utilitaire blanc (immatriculation LK-551-YL) est associé au passage, et une fausse carte professionnelle a été présentée. La victime, isolée, n''a pas toujours conservé de description précise ni relevé l''immatriculation complète. Fait isolé en apparence, mais dont la signature recoupe des signalements dispersés sur d''autres communes ; à recouper au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'faux agent', 0);
