INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Vols de matériel agricole', 'BTA Arcachon', 'GGD 33', 'Gironde', 'Carcans', 'Intrusions nocturnes répétées dans des hangars et bâtiments d''exploitation, avec ouverture forcée de portails et fouille des espaces de stockage. Si aucun vol majeur n''est systématiquement constaté, des traces de repérage préalable (marquages, ouvertures testées, passages réitérés) sont relevées, suggérant une préparation en vue de faits ultérieurs. Les propriétaires signalent des chiens agités et des déclenchements d''éclairage plusieurs nuits d''affilée. Aucun auteur n''a été interpellé. Le mode opératoire évoque un secteur en cours de ''reconnaissance''. Renseignement à intégrer à la surveillance des zones agricoles isolées et à recouper avec les faits voisins.');
