INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'réseaux', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Faux agents à domicile', 'COB Béziers', 'GGD 34', 'Hérault', 'Loupian', 'Vague d''appels téléphoniques ciblant des séniors isolés, l''interlocuteur usurpant la qualité d''agent administratif ou bancaire pour instaurer un climat d''urgence. Sous couvert d''une prétendue anomalie sur un compte ou d''un remboursement à régulariser, il cherche à obtenir des coordonnées bancaires, des codes ou un rendez-vous à domicile. Plusieurs personnes rapportent des appels répétés depuis des numéros masqués ou usurpés. Le discours, rodé et insistant, vise à contourner la méfiance des victimes. Aucun préjudice financier n''est confirmé pour l''instant. Phénomène à signaler en prévention et à rapprocher des campagnes d''escroquerie recensées au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'personnes âgées', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'démarchage', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Tensions autour d''une rencontre sportive', 'BTA Béziers', 'GGD 34', 'Hérault', 'Ceyras', 'Déplacement annoncé d''un groupe de supporters classé à risque à l''occasion d''une rencontre à l''extérieur, avec constitution d''un convoi routier repéré sur l''axe principal (dont un véhicule immatriculé EC-336-CJ). Les échanges en amont, relayés dans des espaces de discussion fermés, laissent entrevoir une volonté de confrontation avec les supporters adverses. Les horaires et points de convergence évoquent un rendez-vous coordonné. Aucun incident constaté au moment de la remontée. Éléments à porter à la connaissance des unités concernées le long de l''itinéraire et à recouper avec les renseignements d''ordre public existants.');
