INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Détention d''arme signalée', 'CGD Nancy', 'GGD 54', 'Meurthe-et-Moselle', 'Boismont', 'Signalement faisant état de la détention possible d''une arme de poing par un individu au comportement menaçant, qui l''aurait exhibée ou évoquée à l''occasion d''un différend de voisinage. La source, indirecte, rapporte des propos alarmants tenus par l''intéressé. Un véhicule (immatriculation KZ-435-JZ) lui est associé. Aucune arme n''a été constatée directement par les enquêteurs à ce stade, et l''origine comme la nature exacte de l''objet restent à établir. La montée de tension locale justifie une évaluation attentive. Renseignement à recouper avec les antécédents éventuels et à sécuriser en vue d''une possible judiciarisation.');
