INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'defaut:B6', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Rodéos motorisés récurrents', 'EDSR 63', 'GGD 63', 'Puy-de-Dôme', 'Royat', 'Depuis une dizaine de jours, signalements répétés de rodéos motorisés en soirée, principalement entre 21h00 et minuit, sur les axes desservant le quartier et ses abords immédiats. Un deux-roues non homologué (50cc débridé) apparaît impliqué à plusieurs reprises ; immatriculation partielle relevée par un riverain : WP-859-SA. Les individus, décrits comme de jeunes majeurs résidant vraisemblablement sur place, adoptent une conduite dangereuse (roues arrière prolongées, remontées de file, franchissements de feux) et se dispersent à l''approche des patrouilles. Aucun n''a pu être formellement identifié à ce stade. Nuisances sonores nocturnes et sentiment d''insécurité croissants rapportés par plusieurs familles ; phénomène à surveiller et à recouper avec les mains courantes des unités voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'rodéo', 0);
