INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'exploitation', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Repérage sur site industriel', 'CGD Pau', 'GGD 64', 'Pyrénées-Atlantiques', 'Castétis', 'Distribution de tracts sur la voie publique appelant au blocage d''un chantier local présenté comme écologiquement contesté, l''appel étant également relayé par le compte @silence_radio (facebook.com/anon1789) annonçant une action à venir. Un participant, contrôlé sur place lors de la distribution, a été identifié : Yanis FONTAINE, né(e) le 17/08/1970, déjà connu(e) pour sa participation à des actions de blocage. Le discours diffusé prône une mobilisation déterminée mais ne comporte pas d''appel explicite à la violence. La date et le lieu précis de l''action annoncée restent à confirmer. Renseignement à recouper avec les mouvements militants régionaux et à intégrer à l''anticipation des troubles à l''ordre public.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'blocage', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'site', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Dégradation de permanence', 'BTA Bayonne', 'GGD 64', 'Pyrénées-Atlantiques', 'Ainhoa', 'Un élu local fait état de la réception, à sa permanence et à son domicile, de plusieurs courriers anonymes au ton menaçant sur une période courte. Les écrits, au vocabulaire revendicatif, sont explicitement liés à un projet d''aménagement contesté sur la commune. Aucune menace de passage à l''acte datée n''y figure, mais la répétition et la montée en intensité inquiètent l''intéressé, qui a modifié ses habitudes. Aucun auteur n''est identifié à ce stade ; un rapprochement est à effectuer avec les prises de position publiques récentes sur le dossier. Les originaux ont été conservés. Renseignement à suivre et à recouper avec d''éventuels faits similaires visant d''autres élus du secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'élu', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'menaces', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Faux agents à domicile', 'COB Pau', 'GGD 64', 'Pyrénées-Atlantiques', 'Castagnède', 'Vague d''appels téléphoniques ciblant des séniors isolés, l''interlocuteur usurpant la qualité d''agent administratif ou bancaire pour instaurer un climat d''urgence. Sous couvert d''une prétendue anomalie sur un compte ou d''un remboursement à régulariser, il cherche à obtenir des coordonnées bancaires, des codes ou un rendez-vous à domicile. Plusieurs personnes rapportent des appels répétés depuis des numéros masqués ou usurpés. Le discours, rodé et insistant, vise à contourner la méfiance des victimes. Aucun préjudice financier n''est confirmé pour l''instant. Phénomène à signaler en prévention et à rapprocher des campagnes d''escroquerie recensées au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'personnes âgées', 1);
