INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Changement de comportement signalé', 'BTA Montmorillon', 'GGD 86', 'Vienne', 'Migné-Auxances', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @ombre_noire (discord.gg/oeil_ouvert) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Julie MOREAU, né(e) le 16/04/1969 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'comportement', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'réseaux', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Intrusions sur exploitation', 'BTA Poitiers', 'GGD 86', 'Vienne', 'Paizay-le-Sec', 'Intrusions nocturnes répétées dans des hangars et bâtiments d''exploitation, avec ouverture forcée de portails et fouille des espaces de stockage. Si aucun vol majeur n''est systématiquement constaté, des traces de repérage préalable (marquages, ouvertures testées, passages réitérés) sont relevées, suggérant une préparation en vue de faits ultérieurs. Les propriétaires signalent des chiens agités et des déclenchements d''éclairage plusieurs nuits d''affilée. Aucun auteur n''a été interpellé. Le mode opératoire évoque un secteur en cours de ''reconnaissance''. Renseignement à intégrer à la surveillance des zones agricoles isolées et à recouper avec les faits voisins.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'agricole', 0);
