INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-20', 'Repérage sur site industriel', 'COB Poitiers', 'GGD 86', 'Vienne', 'Saint-Laon', 'Deux personnes ont été observées photographiant et filmant les accès, clôtures et postes de contrôle d''un site industriel classé, avant de se replier à bord d''un véhicule de tourisme (immatriculation ZS-506-LR) stationné à l''écart. Leur comportement (repérage méthodique des points d''entrée, attention portée aux caméras et aux horaires de rondes) évoque une phase de préparation. En parallèle, une mobilisation visant ce type d''installations est relayée en ligne sur tiktok.com/@libre_2026. Aucune action n''a été engagée sur place à ce jour. Éléments à rapprocher des appels militants en cours et à porter à la connaissance de l''exploitant pour renforcement de la vigilance ; suivi à assurer.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
