INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Survol de drone au-dessus d''un site sensible', 'PSIG Aix-en-Provence', 'GGD 13', 'Bouches-du-Rhône', 'Jouques', 'Survol répété d''un drone au-dessus d''un site sensible (dépôt d''hydrocarbures, emprise clôturée, infrastructure) en soirée et à la tombée de la nuit, sur plusieurs occurrences rapprochées. Les trajectoires, lentes et stationnaires au-dessus des points d''intérêt, évoquent une manœuvre de reconnaissance plutôt qu''un usage de loisir. Aucun télépilote n''a pu être localisé, l''appareil disparaissant dès l''arrivée des moyens. Un véhicule de tourisme (immatriculation HY-900-DP) a été observé stationnant à proximité au moment des faits, occupant à bord, puis quittant les lieux. Aucune atteinte matérielle constatée. Fait en apparence localisé, mais dont la signature recoupe des survols signalés sur d''autres emprises sensibles du secteur ; à recouper d''urgence au plan zonal.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'drone', 0);
