INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Faux agents à domicile', 'COB Sète', 'GGD 34', 'Hérault', 'Saint-Jean-de-Cornies', 'Plusieurs personnes âgées d''un même secteur ont été démarchées à domicile, sur une courte période, par un individu se présentant comme agent d''un service public et exhibant un badge non vérifiable. Sous prétexte d''un contrôle technique ou administratif urgent, l''homme tente d''obtenir l''accès au logement et de détourner l''attention des occupants. Un véhicule utilitaire blanc (immatriculation BN-871-SE) est associé à ces passages. Aucune remise de fonds n''est confirmée à ce stade, mais le mode opératoire est caractéristique des équipes itinérantes de faux agents. Les victimes, isolées, n''ont pas toutes conservé de description précise. Renseignement à diffuser en prévention et à recouper avec les faits des communes voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'personnes âgées', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'démarchage', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Vols de matériel agricole', 'EDSR 34', 'GGD 34', 'Hérault', 'Saussan', 'Intrusions nocturnes répétées dans des hangars et bâtiments d''exploitation, avec ouverture forcée de portails et fouille des espaces de stockage. Si aucun vol majeur n''est systématiquement constaté, des traces de repérage préalable (marquages, ouvertures testées, passages réitérés) sont relevées, suggérant une préparation en vue de faits ultérieurs. Les propriétaires signalent des chiens agités et des déclenchements d''éclairage plusieurs nuits d''affilée. Aucun auteur n''a été interpellé. Le mode opératoire évoque un secteur en cours de ''reconnaissance''. Renseignement à intégrer à la surveillance des zones agricoles isolées et à recouper avec les faits voisins.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'agricole', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vol', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'exploitation', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Vols de matériel agricole', 'COB Sète', 'GGD 34', 'Hérault', 'Puissalicon', 'Série de vols de GPS de guidage, de batteries et d''outillage spécialisé commis sur plusieurs exploitations agricoles isolées d''un même secteur, sur une période resserrée. Les faits, commis de nuit, visent des matériels de valeur revendables et dénotent une bonne connaissance des lieux et des équipements ciblés. Une camionnette (immatriculation MJ-315-BL) a été signalée circulant de nuit sur les chemins ruraux desservant les parcelles concernées. Les exploitants déplorent un préjudice cumulé important et un sentiment d''exposition croissant. Aucun auteur interpellé à ce jour. Faits à rapprocher d''une possible équipe itinérante et à recouper avec les vols similaires des départements limitrophes.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'agricole', 0);
