INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Propos préoccupants en ligne', 'PSIG Châteauroux', 'GGD 36', 'Indre', 'Rosnay', 'Signalement émanant d''un proche faisant état d''un changement rapide et marqué de comportement chez un individu : rupture avec l''entourage habituel, adoption d''un discours rigoriste et rejet des institutions sur une période courte. L''intéressé, contrôlé lors d''un déplacement routier, a été identifié : Émilie NGUYEN, né(e) le 04/10/1978 ; aucune infraction relevée à cette occasion. Le proche décrit un repli progressif et de nouvelles fréquentations mal identifiées. Aucun élément ne permet à ce stade de caractériser un projet ou une menace. Renseignement à évaluer avec mesure, à recouper avec les autres remontées et à porter, le cas échéant, à la connaissance des services spécialisés.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
