INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Menaces envers un élu local', 'COB Cosne-Cours-sur-Loire', 'GGD 58', 'Nièvre', 'Rémilly', 'Inscriptions hostiles et injurieuses taguées durant la nuit sur la façade et la vitrine d''une permanence d''élu, visant nommément l''intéressé et un projet local. Dégradations découvertes à l''ouverture ; aucun témoin direct. Un véhicule de tourisme (immatriculation SX-439-XG) a été aperçu par un riverain quittant les lieux à vive allure peu avant, sans que le lien soit établi. Le mode opératoire (intervention nocturne, message ciblé) s''inscrit dans un climat de tension autour du dossier concerné. Faits à rapprocher d''autres dégradations à caractère revendicatif signalées récemment ; suivi à assurer.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'élu', 0);
