INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Changement de comportement signalé', 'BTA Autun', 'GGD 71', 'Saône-et-Loire', 'Gilly-sur-Loire', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @veritas_fr (instagram.com/resistance84) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Hugo FONTAINE, né(e) le 01/12/1970 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
