INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Repérage suspect en zone d''exploitation', 'BR Le Mans', 'GGD 72', 'Sarthe', 'Dollon', 'Véhicule de tourisme (immatriculation YE-776-WR) observé à plusieurs reprises stationnant à proximité d''exploitations agricoles isolées, ses occupants paraissant observer les hangars, les accès et les matériels entreposés. Le véhicule redémarre systématiquement à l''arrivée d''un tiers ou de l''exploitant, ce qui écarte l''hypothèse d''un simple arrêt fortuit. Aucun vol ni dégradation n''est constaté ce jour : le comportement relève de l''observation et du repérage préalable. Les exploitants concernés font état d''un sentiment de surveillance inhabituel. Fait apparemment isolé, mais dont la signature recoupe des repérages signalés autour d''autres exploitations du secteur ; à recouper et à intégrer à la surveillance des zones agricoles.');
