INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Détention d''arme signalée', 'COB Moissac', 'GGD 82', 'Tarn-et-Garonne', 'Saint-Étienne-de-Tulmont', 'Renseignement faisant état d''une transaction d''arme présumée devant intervenir sur un parking isolé, à l''écart des zones fréquentées et sur un créneau discret. Un participant, contrôlé à proximité, a été identifié : Hugo RIVIERE, né(e) le 20/07/2004. Les modalités décrites (rendez-vous bref, remise d''un objet volumineux dissimulé, méfiance marquée des protagonistes) sont cohérentes avec un échange clandestin, sans que la nature de l''objet soit établie. Aucune saisie n''a été opérée. La fiabilité de la source reste à confirmer. Élément à recouper d''urgence avec les renseignements relatifs au trafic d''armes dans le secteur.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'arme', 0);
