INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Tract appelant au blocage', 'COB Sarcelles', 'GGD 95', 'Val-d''Oise', 'Arnouville', 'Distribution de tracts sur la voie publique appelant au blocage d''un chantier local présenté comme écologiquement contesté, l''appel étant également relayé par le compte @anon1789 (instagram.com/oeil_ouvert) annonçant une action à venir. Un participant, contrôlé sur place lors de la distribution, a été identifié : Inès HADDAD, né(e) le 04/11/1996, déjà connu(e) pour sa participation à des actions de blocage. Le discours diffusé prône une mobilisation déterminée mais ne comporte pas d''appel explicite à la violence. La date et le lieu précis de l''action annoncée restent à confirmer. Renseignement à recouper avec les mouvements militants régionaux et à intégrer à l''anticipation des troubles à l''ordre public.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'blocage', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'site', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Emprise sur personne vulnérable', 'COB Sarcelles', 'GGD 95', 'Val-d''Oise', 'Asnières-sur-Oise', 'Une famille s''inquiète de l''isolement croissant d''un proche depuis son adhésion à un groupe se présentant comme dédié au ''développement personnel''. Les réunions, fréquentes et tenues en zone rurale au domicile de l''un des membres, s''accompagneraient d''un discours de rupture avec l''entourage et d''une pression financière (contributions, stages payants). Le proche aurait progressivement cessé ses activités habituelles et espacé les contacts familiaux. Aucun élément pénal n''est caractérisé à ce stade, mais les indices d''emprise et de vulnérabilité sont réunis. Situation à évaluer avec prudence et à porter à la connaissance des services compétents ; à recouper avec d''éventuels signalements analogues.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Groupe de développement personnel signalé', 'BTA Gonesse', 'GGD 95', 'Val-d''Oise', 'Nucourt', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Yanis MASSON, né(e) le 26/12/2001 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
