INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Emprise sur personne vulnérable', 'CGD Mamoudzou', 'GGD 976', 'Mayotte', 'Dembeni', 'Rassemblement récurrent constaté dans une propriété isolée accueillant, plusieurs fois par semaine, un groupe restreint autour d''un animateur au discours communautaire marqué. Le voisinage rapporte des allées et venues discrètes et la présence de personnes paraissant en situation de vulnérabilité. L''animateur, contrôlé lors d''un déplacement routier, a été identifié comme M./Mme Nadia ROUSSEAU, né(e) le 17/03/1998 ; aucune infraction n''a été relevée à cette occasion. Le fonctionnement (mise à l''écart de l''entourage, ascendant d''une figure centrale) appelle une vigilance particulière. Renseignement à recouper et à suivre dans la durée, sans caractérisation pénale à ce stade.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Groupe de supporters à risque', 'COB Koungou', 'GGD 976', 'Mayotte', 'Kani-Kéli', 'Déplacement annoncé d''un groupe de supporters classé à risque à l''occasion d''une rencontre à l''extérieur, avec constitution d''un convoi routier repéré sur l''axe principal (dont un véhicule immatriculé EK-681-FA). Les échanges en amont, relayés dans des espaces de discussion fermés, laissent entrevoir une volonté de confrontation avec les supporters adverses. Les horaires et points de convergence évoquent un rendez-vous coordonné. Aucun incident constaté au moment de la remontée. Éléments à porter à la connaissance des unités concernées le long de l''itinéraire et à recouper avec les renseignements d''ordre public existants.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'supporters', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'rencontre', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'ordre public', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Faux agents à domicile', 'BR Mamoudzou', 'GGD 976', 'Mayotte', 'Acoua', 'Plusieurs personnes âgées d''un même secteur ont été démarchées à domicile, sur une courte période, par un individu se présentant comme agent d''un service public et exhibant un badge non vérifiable. Sous prétexte d''un contrôle technique ou administratif urgent, l''homme tente d''obtenir l''accès au logement et de détourner l''attention des occupants. Un véhicule utilitaire blanc (immatriculation GB-269-GZ) est associé à ces passages. Aucune remise de fonds n''est confirmée à ce stade, mais le mode opératoire est caractéristique des équipes itinérantes de faux agents. Les victimes, isolées, n''ont pas toutes conservé de description précise. Renseignement à diffuser en prévention et à recouper avec les faits des communes voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'personnes âgées', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'démarchage', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Groupe de supporters à risque', 'EDSR 976', 'GGD 976', 'Mayotte', 'Dembeni', 'En marge d''une rencontre sportive, un groupe de supporters a été signalé pour un comportement agressif aux abords de l''enceinte : usage de fumigènes, provocations et échauffourées évitées de justesse grâce au dispositif en place. Un individu, contrôlé à cette occasion, a été identifié : Inès MASSON, né(e) le 16/10/2004, déjà connu pour des faits similaires. Des tensions préexistantes avec un groupe rival sont rapportées et pourraient ressurgir lors des prochaines échéances. Aucune interpellation pour violences à ce stade. Renseignement à intégrer à la préparation des futurs matchs et à recouper avec les fiches des groupes à risque connus au plan régional.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'supporters', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'rencontre', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'ordre public', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-21', 'Démarchage frauduleux de séniors', 'BTA Mamoudzou', 'GGD 976', 'Mayotte', 'Dembeni', 'Plusieurs personnes âgées d''un même secteur ont été démarchées à domicile, sur une courte période, par un individu se présentant comme agent d''un service public et exhibant un badge non vérifiable. Sous prétexte d''un contrôle technique ou administratif urgent, l''homme tente d''obtenir l''accès au logement et de détourner l''attention des occupants. Un véhicule utilitaire blanc (immatriculation ZF-554-SK) est associé à ces passages. Aucune remise de fonds n''est confirmée à ce stade, mais le mode opératoire est caractéristique des équipes itinérantes de faux agents. Les victimes, isolées, n''ont pas toutes conservé de description précise. Renseignement à diffuser en prévention et à recouper avec les faits des communes voisines.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
