INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Emprise sur personne vulnérable', 'BTA Laon', 'GGD 02', 'Aisne', 'Rocquigny', 'Une famille s''inquiète de l''isolement croissant d''un proche depuis son adhésion à un groupe se présentant comme dédié au ''développement personnel''. Les réunions, fréquentes et tenues en zone rurale au domicile de l''un des membres, s''accompagneraient d''un discours de rupture avec l''entourage et d''une pression financière (contributions, stages payants). Le proche aurait progressivement cessé ses activités habituelles et espacé les contacts familiaux. Aucun élément pénal n''est caractérisé à ce stade, mais les indices d''emprise et de vulnérabilité sont réunis. Situation à évaluer avec prudence et à porter à la connaissance des services compétents ; à recouper avec d''éventuels signalements analogues.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
