INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Tensions autour d''une rencontre sportive', 'EDSR 08', 'GGD 08', 'Ardennes', 'Sailly', 'En marge d''une rencontre sportive, un groupe de supporters a été signalé pour un comportement agressif aux abords de l''enceinte : usage de fumigènes, provocations et échauffourées évitées de justesse grâce au dispositif en place. Un individu, contrôlé à cette occasion, a été identifié : Bilal BERNARD, né(e) le 25/08/1995, déjà connu pour des faits similaires. Des tensions préexistantes avec un groupe rival sont rapportées et pourraient ressurgir lors des prochaines échéances. Aucune interpellation pour violences à ce stade. Renseignement à intégrer à la préparation des futurs matchs et à recouper avec les fiches des groupes à risque connus au plan régional.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'supporters', 0);
