INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Point de deal présumé', 'BTA Bayeux', 'GGD 14', 'Calvados', 'Montreuil-en-Auge', 'Va-et-vient nocturnes réguliers observés autour d''un hall d''immeuble, principalement en fin de soirée et en début de nuit, avec présence de guetteurs postés en entrée de rue et en pied d''immeuble donnant l''alerte à l''approche de tout véhicule. Une berline sombre (immatriculation DP-412-RV) effectue des passages courts et répétés, marquant de brefs arrêts avant de repartir. Les échanges, rapides et discrets, sont cohérents avec une activité de vente au détail. Plusieurs habitants font état d''un climat d''intimidation et évitent désormais les parties communes en soirée. Aucun mis en cause identifié à ce jour ; renseignement à recouper avec les doléances déjà enregistrées sur le secteur.');
