INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Démarchage par faux agent — mode opératoire identique', 'COB Rochefort', 'GGD 17', 'Charente-Maritime', 'Courant', 'Personne âgée démarchée à son domicile par un homme se présentant comme agent d''un organisme officiel, muni d''un gilet et d''un badge non vérifiables. Même mode opératoire que d''autres faits récents : prétexte d''un contrôle urgent (compteur, canalisation, mise aux normes), insistance pour entrer, tentative de détourner l''attention pendant qu''un second individu resterait à l''extérieur. Un véhicule utilitaire blanc (immatriculation ZH-201-ED) est associé au passage, et une fausse carte professionnelle a été présentée. La victime, isolée, n''a pas toujours conservé de description précise ni relevé l''immatriculation complète. Fait isolé en apparence, mais dont la signature recoupe des signalements dispersés sur d''autres communes ; à recouper au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'faux agent', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'utilitaire blanc', 1);
