INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Emprise sur personne vulnérable', 'COB Sarlat-la-Canéda', 'GGD 24', 'Dordogne', 'Saint-Michel-de-Villadeix', 'Une famille s''inquiète de l''isolement croissant d''un proche depuis son adhésion à un groupe se présentant comme dédié au ''développement personnel''. Les réunions, fréquentes et tenues en zone rurale au domicile de l''un des membres, s''accompagneraient d''un discours de rupture avec l''entourage et d''une pression financière (contributions, stages payants). Le proche aurait progressivement cessé ses activités habituelles et espacé les contacts familiaux. Aucun élément pénal n''est caractérisé à ce stade, mais les indices d''emprise et de vulnérabilité sont réunis. Situation à évaluer avec prudence et à porter à la connaissance des services compétents ; à recouper avec d''éventuels signalements analogues.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'communauté', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vulnérabilité', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Propos préoccupants en ligne', 'CGD Périgueux', 'GGD 24', 'Dordogne', 'La Force', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @colere_rurale (tiktok.com/@resistance84) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Fatima LEROY, né(e) le 08/07/1993 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
