INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Emprise sur personne vulnérable', 'BR Toulouse', 'GGD 31', 'Haute-Garonne', 'Herran', 'Une famille s''inquiète de l''isolement croissant d''un proche depuis son adhésion à un groupe se présentant comme dédié au ''développement personnel''. Les réunions, fréquentes et tenues en zone rurale au domicile de l''un des membres, s''accompagneraient d''un discours de rupture avec l''entourage et d''une pression financière (contributions, stages payants). Le proche aurait progressivement cessé ses activités habituelles et espacé les contacts familiaux. Aucun élément pénal n''est caractérisé à ce stade, mais les indices d''emprise et de vulnérabilité sont réunis. Situation à évaluer avec prudence et à porter à la connaissance des services compétents ; à recouper avec d''éventuels signalements analogues. Vérification faite, il s''agit d''un différend de voisinage relatif à une haie mitoyenne : aucune violence, aucune menace, médiation acceptée par les deux parties.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'emprise', 0);
