INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Propos préoccupants en ligne', 'BR Rennes', 'GGD 35', 'Ille-et-Vilaine', 'Chelun', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @colere_rurale (x.com/silence_radio) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Inès NGUYEN, né(e) le 23/06/1978 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
