INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Propos préoccupants en ligne', 'COB Le Puy-en-Velay', 'GGD 43', 'Haute-Loire', 'Siaugues-Sainte-Marie', 'Propos préoccupants relevés sur un réseau social et signalés par un tiers. Le compte @silence_radio (discord.gg/ombre_noire) diffuse un discours de rupture et des contenus valorisant l''affrontement avec les institutions ; le titulaire présumé serait Camille FERHAT, né(e) le 14/12/1978 (identité à confirmer). La montée en tonalité des publications sur une courte période et l''écho recherché auprès d''un public jeune sont notés. Aucun appel direct et daté à commettre des faits n''est identifié à ce stade. Les contenus sont à évaluer, à horodater et à recouper avant toute qualification. Renseignement à transmettre aux services compétents pour appréciation.');
