INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'quartier', 3);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Rodéos motorisés récurrents', 'CGD La Roche-sur-Yon', 'GGD 85', 'Vendée', 'Saint-Hilaire-de-Riez', 'Attroupement d''une dizaine d''individus en début de nuit ayant occasionné des jets de projectiles (bouteilles en verre, pierres) sur la voie publique et en direction d''un abribus. Aucun blessé ni dégât matériel majeur constaté, la dispersion étant intervenue spontanément à l''arrivée des premiers moyens. Un véhicule utilitaire de couleur claire (immatriculation KE-181-SX) a été aperçu stationnant à proximité immédiate, puis quittant les lieux au même moment ; lien à confirmer. Le mode opératoire et le créneau horaire recoupent d''autres épisodes signalés dans le secteur les jours précédents. Aucune revendication. Élément à rapprocher des remontées locales et à intégrer au suivi du quartier.');
