INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'permanence', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Intrusions sur exploitation', 'CGD Étampes', 'GGD 91', 'Essonne', 'Boutervilliers', 'Intrusions nocturnes répétées dans des hangars et bâtiments d''exploitation, avec ouverture forcée de portails et fouille des espaces de stockage. Si aucun vol majeur n''est systématiquement constaté, des traces de repérage préalable (marquages, ouvertures testées, passages réitérés) sont relevées, suggérant une préparation en vue de faits ultérieurs. Les propriétaires signalent des chiens agités et des déclenchements d''éclairage plusieurs nuits d''affilée. Aucun auteur n''a été interpellé. Le mode opératoire évoque un secteur en cours de ''reconnaissance''. Renseignement à intégrer à la surveillance des zones agricoles isolées et à recouper avec les faits voisins.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'agricole', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'vol', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'exploitation', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Propos préoccupants en ligne', 'BTA Étampes', 'GGD 91', 'Essonne', 'Grigny', 'Signalement émanant d''un proche faisant état d''un changement rapide et marqué de comportement chez un individu : rupture avec l''entourage habituel, adoption d''un discours rigoriste et rejet des institutions sur une période courte. L''intéressé, contrôlé lors d''un déplacement routier, a été identifié : Camille NGUYEN, né(e) le 18/05/1981 ; aucune infraction relevée à cette occasion. Le proche décrit un repli progressif et de nouvelles fréquentations mal identifiées. Aucun élément ne permet à ce stade de caractériser un projet ou une menace. Renseignement à évaluer avec mesure, à recouper avec les autres remontées et à porter, le cas échéant, à la connaissance des services spécialisés.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'signalement', 0);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'comportement', 1);
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'réseaux', 2);
INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Démarchage frauduleux de séniors', 'COB Dourdan', 'GGD 91', 'Essonne', 'Boissy-la-Rivière', 'Vague d''appels téléphoniques ciblant des séniors isolés, l''interlocuteur usurpant la qualité d''agent administratif ou bancaire pour instaurer un climat d''urgence. Sous couvert d''une prétendue anomalie sur un compte ou d''un remboursement à régulariser, il cherche à obtenir des coordonnées bancaires, des codes ou un rendez-vous à domicile. Plusieurs personnes rapportent des appels répétés depuis des numéros masqués ou usurpés. Le discours, rodé et insistant, vise à contourner la méfiance des victimes. Aucun préjudice financier n''est confirmé pour l''instant. Phénomène à signaler en prévention et à rapprocher des campagnes d''escroquerie recensées au plan départemental.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'escroquerie', 0);
