INSERT INTO frs (date_redaction, titre, unite, code_ggd, departement, commune, texte) VALUES ('2026-07-22', 'Repérage sur site industriel', 'BTA Sarcelles', 'GGD 95', 'Val-d''Oise', 'Le Thillay', 'Deux personnes ont été observées photographiant et filmant les accès, clôtures et postes de contrôle d''un site industriel classé, avant de se replier à bord d''un véhicule de tourisme (immatriculation RQ-862-QY) stationné à l''écart. Leur comportement (repérage méthodique des points d''entrée, attention portée aux caméras et aux horaires de rondes) évoque une phase de préparation. En parallèle, une mobilisation visant ce type d''installations est relayée en ligne sur instagram.com/nuit_du_sud. Aucune action n''a été engagée sur place à ce jour. Éléments à rapprocher des appels militants en cours et à porter à la connaissance de l''exploitant pour renforcement de la vigilance ; suivi à assurer.');
INSERT INTO frs_mot_cle (frs_id, mot, ordre) VALUES (currval('frs_id_seq'), 'militants', 0);
